export const VITALS = [
  { key: 'bp', label: 'Presión arterial', short: 'PRESIÓN ARTERIAL', unit: 'mmHg', tool: 'Tensiómetro', icon: '◉', steps: ['Higieniza tus manos y explica el procedimiento.', 'Coloca el brazalete ajustado en el brazo, sobre la piel.', 'Mantén el brazo apoyado a la altura del corazón.', 'Inicia la medición y espera a que el equipo termine.'], actions: ['Higiene + explicación', 'Colocar brazalete', 'Posicionar brazo', 'Iniciar medición'], value: c => `${c.vitals.bp[0]}/${c.vitals.bp[1]}` },
  { key: 'hr', label: 'Frecuencia cardíaca', short: 'FRECUENCIA CARDÍACA', unit: 'lpm', tool: 'Estetoscopio + reloj', icon: '♥', steps: ['Informa al paciente y permite que repose un momento.', 'Localiza el pulso radial con índice y medio (no el pulgar).', 'Cuenta los latidos durante 60 segundos en esta práctica.', 'Registra la frecuencia y compara el ritmo observado.'], actions: ['Preparar al paciente', 'Localizar pulso radial', 'Iniciar conteo · 60 s', 'Registrar frecuencia'], value: c => `${c.vitals.hr}` },
  { key: 'rr', label: 'Frecuencia respiratoria', short: 'FRECUENCIA RESPIRATORIA', unit: 'rpm', tool: 'Reloj / observación', icon: '⌁', steps: ['Procura observar sin alterar el patrón respiratorio.', 'Observa el tórax: una subida y bajada es un ciclo.', 'Cuenta ciclos durante 60 segundos en esta práctica.', 'Registra frecuencia, ritmo y esfuerzo observado.'], actions: ['Observar discretamente', 'Identificar un ciclo', 'Iniciar conteo · 60 s', 'Registrar respiraciones'], value: c => `${c.vitals.rr}` },
  { key: 'spo2', label: 'Saturación de oxígeno', short: 'SATURACIÓN O₂', unit: '%', tool: 'Pulsioxímetro', icon: '◌', steps: ['Comprueba que el dedo esté tibio y sin esmalte opaco.', 'Coloca el sensor correctamente en un dedo.', 'Espera a que la lectura se estabilice.', 'Registra el porcentaje junto con el contexto clínico.'], actions: ['Revisar el dedo', 'Colocar sensor', 'Esperar señal estable', 'Registrar SpO₂'], value: c => `${c.vitals.spo2}` },
  { key: 'temp', label: 'Temperatura corporal', short: 'TEMPERATURA', unit: '°C', tool: 'Termómetro digital', icon: '♨', steps: ['Explica la medición y selecciona el sitio indicado.', 'Prepara el termómetro según las instrucciones del equipo.', 'Realiza la lectura simulada y espera la señal.', 'Registra temperatura, sitio y método de medición.'], actions: ['Elegir sitio de medición', 'Preparar termómetro', 'Realizar lectura', 'Registrar temperatura'], value: c => `${c.vitals.temp.toFixed(1)}` },
  { key: 'pulse', label: 'Pulso periférico', short: 'PULSO PERIFÉRICO', unit: 'lpm · evaluación', tool: 'Reloj / palpación', icon: '≈', steps: ['Elige el sitio apropiado y explica antes de tocar.', 'Palpa suavemente con índice y medio.', 'Valora frecuencia, ritmo, amplitud y simetría.', 'Registra características; compáralas con la frecuencia cardíaca.'], actions: ['Elegir sitio de palpación', 'Palpar suavemente', 'Valorar ritmo y amplitud', 'Registrar hallazgos'], value: c => `${c.vitals.pulse} · ${c.vitals.pulseQuality}` },
];

export const CASES = [
  { id: 'VF–001', title: 'Evaluación de rutina', name: 'Alex Rivera', age: 28, initials: 'AR', reason: 'Cansancio', location: 'Sala de observación', difficulty: 'INICIAL', description: 'Completa la valoración inicial y registra los signos vitales.', history: 'Sin antecedentes relevantes referidos. Refiere cansancio desde hace dos días.', observation: 'Paciente alerta, conversa con normalidad y permanece en reposo.', vitals: { bp: [120,80], hr:82, rr:16, spo2:98, temp:36.7, pulse:82, pulseQuality:'regular, amplitud moderada' }, note: 'Práctica de registro basal. Interpreta el conjunto y el contexto, no un número aislado.', xp: 120, coins: 80 },
  { id: 'VF–002', title: 'Malestar y fiebre', name: 'Lucía Méndez', age: 34, initials: 'LM', reason: 'Sensación febril', location: 'Consultorio 02', difficulty: 'BÁSICO', description: 'Valora signos vitales, registra el método y comunica el hallazgo.', history: 'Refiere malestar general desde esta mañana. Sin alergias registradas en esta simulación.', observation: 'Piel tibia; paciente alerta. Se recomienda registrar contexto y comunicar cambios al responsable.', vitals: { bp:[118,76], hr:96, rr:19, spo2:97, temp:38.2, pulse:96, pulseQuality:'regular, amplitud moderada' }, note:'La temperatura elevada simulada merece valoración contextual y comunicación; no establece por sí sola un diagnóstico.', xp:160, coins:100 },
  { id: 'VF–003', title: 'Respiración bajo observación', name: 'Mateo Solís', age: 61, initials: 'MS', reason: 'Falta de aire al esfuerzo', location: 'Urgencias · cubículo 1', difficulty: 'INTERMEDIO', description: 'Prioriza observación respiratoria, SpO₂ y comunicación de cualquier cambio.', history: 'Antecedente simulado de asma. Refiere falta de aire al caminar; sentado y acompañado.', observation: 'Respiración algo rápida en la escena. Comunica de inmediato cualquier empeoramiento al personal responsable.', vitals: { bp:[136,84], hr:108, rr:24, spo2:92, temp:37.1, pulse:108, pulseQuality:'regular, amplitud moderada' }, note:'El caso representa señales que requieren evaluación contextual rápida por el equipo responsable. No es una guía de triaje.', xp:200, coins:130 },
  { id: 'VF–004', title: 'Mareo y debilidad', name: 'Elena Cruz', age: 72, initials: 'EC', reason: 'Mareo al incorporarse', location: 'Observación · cama 3', difficulty: 'INTERMEDIO', description: 'Registra el conjunto de signos y comunica hallazgos relevantes al responsable.', history: 'Refiere ingesta escasa hoy. Sin datos clínicos adicionales en este caso ficticio.', observation: 'Paciente consciente y acompañada; permanece recostada durante la valoración.', vitals: { bp:[100,66], hr:102, rr:20, spo2:96, temp:36.5, pulse:102, pulseQuality:'regular, amplitud algo débil' }, note:'Considera edad, síntomas, posición y tendencia. Los valores aislados no permiten concluir un diagnóstico.', xp:200, coins:130 },
];

export function classify(caseData, key) {
  const v=caseData.vitals;
  if(key==='temp') return v.temp>=38 ? ['Atención contextual','warning','Temperatura simulada elevada; documenta el método y comunícalo.'] : ['Referencia educativa','normal','Interpreta junto con el estado general y el sitio de medición.'];
  if(key==='spo2') return v.spo2<94 ? ['Comunicar al responsable','warning','Lectura simulada reducida; verifica señal, contexto y comunica el hallazgo.'] : ['Referencia educativa','normal','Registra la lectura y el contexto; considera la calidad de señal.'];
  if(key==='rr') return v.rr>=22 ? ['Comunicar al responsable','warning','Frecuencia simulada elevada; valora esfuerzo y comunica cambios.'] : ['Referencia educativa','normal','Valora ritmo y esfuerzo, además del número.'];
  if(key==='hr'||key==='pulse') return v.hr>=100 || v.hr<60 ? ['Revisar contexto','warning','Compara con síntomas, reposo y características del pulso; comunica si preocupa.'] : ['Referencia educativa','normal','La frecuencia puede variar por actividad, edad y contexto.'];
  if(key==='bp') return v.bp[0]>=140||v.bp[1]>=90||v.bp[0]<90 ? ['Revisar contexto','warning','Un registro aislado no diagnostica; verifica técnica y comunícalo al responsable.'] : ['Referencia educativa','normal','La interpretación depende de técnica, edad, antecedentes y contexto.'];
  return ['Registro guardado','normal','Revisa todos los datos en conjunto.'];
}

