import * as THREE from 'three';
import { CASES, VITALS, classify } from './data.js';
import './styles.css';

const $ = (s) => document.querySelector(s);
const saved = JSON.parse(localStorage.getItem('vital-force-save') || '{}');
const state = {
  caseIndex: Math.min(saved.caseIndex || 0, CASES.length - 1),
  completed: saved.completed || [], xp: saved.xp ?? 120, coins: saved.coins ?? 240,
  measured: saved.measured || {}, started: false, sound: saved.sound ?? true,
  player: new THREE.Vector3(0, 0, 4), keys: new Set(), touch: new Set(),
  procVital: null, procStep: 0, quizDone: saved.quizDone || [],
};
let scene, camera, renderer, player, targetPatient, clock, toastTimer;
const caseMeshes = [];
const c = () => CASES[state.caseIndex];
const esc = (s) => String(s).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));

function initWorld() {
  scene = new THREE.Scene(); scene.background = new THREE.Color('#102b40'); scene.fog = new THREE.Fog('#102b40', 18, 48);
  camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 100);
  renderer = new THREE.WebGLRenderer({ canvas: $('#world'), antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2)); renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap; renderer.outputColorSpace = THREE.SRGBColorSpace;
  scene.add(new THREE.HemisphereLight('#d8f6ff', '#18334a', 2.2));
  const sun = new THREE.DirectionalLight('#fff4df', 2.2); sun.position.set(-5, 10, 4); sun.castShadow = true; sun.shadow.mapSize.set(1024, 1024); scene.add(sun);
  const mat = (color, roughness=.8) => new THREE.MeshStandardMaterial({color, roughness});
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(34, 30), mat('#b8cbd0')); floor.rotation.x=-Math.PI/2; floor.receiveShadow=true; scene.add(floor);
  const grid = new THREE.GridHelper(34, 34, '#7b9ba0', '#9eb6b8'); grid.position.y=.012; grid.material.transparent=true; grid.material.opacity=.16; scene.add(grid);
  const wallMat=mat('#d7e5e3'), accent=mat('#397b87'), glass=new THREE.MeshStandardMaterial({color:'#78d6dc',roughness:.22,metalness:.1});
  function box(x,y,z,w,h,d,m, cast=true) {const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;scene.add(o);return o;}
  // Sala abierta con cubículos, pasillo central y señalética geométrica.
  box(0,3,-15,34,6,.35,wallMat); box(-17,3,0,.35,6,30,wallMat); box(17,3,0,.35,6,30,wallMat);
  box(-9,2,-7,.2,4,10,wallMat); box(9,2,-7,.2,4,10,wallMat);
  box(-13,2,2,8,.18,.18,accent); box(13,2,2,8,.18,.18,accent);
  box(0,3,14,34,6,.3,wallMat);
  // Puertas y ventanas decorativas
  for (const x of [-14,-11,-7,7,11,14]) { const win=box(x,3,-14.78,1.35,1.2,.06,glass,false); win.material=glass; }
  for (let x=-14;x<=14;x+=4) box(x, .02, -14.65, 1.8,.08,.08,accent,false);
  // Mostrador de recepción
  box(-12,.55,10,5,1.1,1.2,mat('#397786')); box(-12,1.16,10,.4,.12,1.3,mat('#e6f4f3'));
  // Camas para las personas de los cuatro casos
  const bedMat=mat('#eaf3f3'), frame=mat('#557887'), sheet=mat('#8bd3d9');
  const spots=[[-5,-9],[5,-9],[-5,7],[5,7]];
  CASES.forEach((ca,i)=>{
    const [x,z]=spots[i]; const group=new THREE.Group(); group.position.set(x,0,z); scene.add(group);
    const bed=new THREE.Group(); group.add(bed);
    const platform=new THREE.Mesh(new THREE.BoxGeometry(2.6,.24,1.35),bedMat);platform.position.set(0,.72,0);platform.castShadow=true;bed.add(platform);
    const mattress=new THREE.Mesh(new THREE.BoxGeometry(2.25,.18,1.2),sheet);mattress.position.set(0,.91,0);bed.add(mattress);
    for (const dx of [-1,1]) for(const dz of [-.48,.48]) {const leg=new THREE.Mesh(new THREE.CylinderGeometry(.045,.055,.7,8),frame);leg.position.set(dx,.35,dz);bed.add(leg);}
    const pillow=new THREE.Mesh(new THREE.BoxGeometry(.62,.16,.9),bedMat);pillow.position.set(-.72,1.1,0);bed.add(pillow);
    const body=new THREE.Group(); body.position.set(.1,1.22,0); group.add(body);
    const skin=mat(i===1?'#bd8b70':i===2?'#b98472':'#d6a88f');
    const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.32,.68,4,8),mat(['#3c9caa','#b77a91','#6087ac','#ad8a55'][i]));torso.rotation.z=Math.PI/2;torso.position.x=.12;torso.castShadow=true;body.add(torso);
    const head=new THREE.Mesh(new THREE.SphereGeometry(.25,16,12),skin);head.position.set(-.72,.1,0);head.castShadow=true;body.add(head);
    const blanket=new THREE.Mesh(new THREE.BoxGeometry(1.05,.14,1.1),mat(['#4aa3ad','#b98394','#5e91b4','#b99b63'][i]));blanket.position.set(.52,.38,0);body.add(blanket);
    const marker=new THREE.Mesh(new THREE.TorusGeometry(.44,.035,8,24),new THREE.MeshBasicMaterial({color:i===state.caseIndex?'#45d6e8':'#41687a'}));marker.rotation.x=-Math.PI/2;marker.position.y=.05;group.add(marker);
    group.userData={caseIndex:i, body, marker};caseMeshes.push(group);
    const sign=box(x,2.4,z-1.6,1.6,.65,.08,mat('#155064'),false); sign.userData.caseIndex=i;
  });
  // Plantas y lámparas para enriquecer el entorno.
  const pot=mat('#315c55'), leaf=mat('#46a879');
  for(const [x,z] of [[-15,-12],[15,-12],[-15,12],[15,12]]) { const p=new THREE.Mesh(new THREE.CylinderGeometry(.35,.42,.55,12),pot);p.position.set(x,.28,z);scene.add(p);for(let n=0;n<5;n++){const l=new THREE.Mesh(new THREE.SphereGeometry(.22,8,8),leaf);l.position.set(x+(Math.random()-.5)*.4,.85+Math.random()*.5,z+(Math.random()-.5)*.4);scene.add(l);}}
  player=new THREE.Group();
  const uniform=mat('#244d69'), face=mat('#c89575');
  const legs=new THREE.Mesh(new THREE.CapsuleGeometry(.18,.48,4,8),mat('#182d42'));legs.position.y=.48;player.add(legs);
  const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.31,.52,4,10),uniform);torso.position.y=1.2;torso.castShadow=true;player.add(torso);
  const head=new THREE.Mesh(new THREE.SphereGeometry(.23,16,12),face);head.position.y=1.94;head.castShadow=true;player.add(head);
  const badge=new THREE.Mesh(new THREE.BoxGeometry(.13,.18,.035),mat('#54d9e7'));badge.position.set(.12,1.28,-.29);player.add(badge);
  player.position.copy(state.player);scene.add(player);clock=new THREE.Clock();
  window.addEventListener('resize',resize); resize(); animate();
}
function resize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight,false);}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);
  let x=0,z=0; const k=state.keys, t=state.touch;
  if(k.has('w')||k.has('arrowup')||t.has('forward'))z-=1;if(k.has('s')||k.has('arrowdown')||t.has('back'))z+=1;if(k.has('a')||k.has('arrowleft')||t.has('left'))x-=1;if(k.has('d')||k.has('arrowright')||t.has('right'))x+=1;
  const moving=!!(x||z); if(moving){const len=Math.hypot(x,z);const speed=(k.has('shift')?6.2:3.8)*dt;x=x/len*speed;z=z/len*speed;state.player.x=THREE.MathUtils.clamp(state.player.x+x,-15.2,15.2);state.player.z=THREE.MathUtils.clamp(state.player.z+z,-13.5,13.4);player.position.copy(state.player);player.rotation.y=Math.atan2(x,z);}
  const desired=new THREE.Vector3(state.player.x+8,11,state.player.z+10);camera.position.lerp(desired,.055);camera.lookAt(state.player.x,0,state.player.z-1);
  caseMeshes.forEach((g,i)=>{g.userData.marker.material.color.set(i===state.caseIndex?'#45d6e8':'#41687a');g.userData.marker.rotation.z+=dt*.15;});
  renderer.render(scene,camera);updateNearby();}

function save(){localStorage.setItem('vital-force-save',JSON.stringify({caseIndex:state.caseIndex,completed:state.completed,xp:state.xp,coins:state.coins,measured:state.measured,quizDone:state.quizDone,sound:state.sound}));}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
function updateHUD(){const ca=c();$('#caseId').textContent=ca.id;$('#missionTitle').textContent=ca.title;$('#missionDescription').textContent=ca.description;$('#patientName').innerHTML=`${esc(ca.name)} <i>${ca.age}</i>`;$('#patientAvatar').textContent=ca.initials;$('#patientReason').textContent=`${ca.reason} · ${ca.location}`;$('#nearbyName').textContent=ca.name;$('#caseCount').textContent=String(CASES.length-state.completed.length).padStart(2,'0');$('#levelTop').textContent=String(1+Math.floor(state.xp/500)).padStart(2,'0');$('#levelLabel').textContent=String(1+Math.floor(state.xp/500)).padStart(2,'0');$('#xpLabel').textContent=`${state.xp%500} / 500 XP`;$('#xpBar').style.width=`${Math.round((state.xp%500)/5)}%`;$('#coinLabel').textContent=state.coins;
 const list=$('#objectiveList');list.innerHTML=VITALS.map(v=>`<div class="objective ${state.measured[ca.id]?.includes(v.key)?'done':''}"><i>${state.measured[ca.id]?.includes(v.key)?'✓':'·'}</i><span>${esc(v.label)}</span></div>`).join('');const done=state.measured[ca.id]?.length||0;$('#objectiveProgress').textContent=`${done} / ${VITALS.length}`;
 caseMeshes.forEach((g,i)=>{g.userData.marker.material.color.set(i===state.caseIndex?'#45d6e8':state.completed.includes(i)?'#43d6a0':'#41687a');});updateNearby();}
function nearestCase(){let best=Infinity,index=0;caseMeshes.forEach((g,i)=>{const d=state.player.distanceTo(g.position);if(d<best){best=d;index=i;}});return {distance:best,index};}
function updateNearby(){if(!caseMeshes.length)return;const {distance,index}=nearestCase();const ca=CASES[index];$('#nearbyName').textContent=ca.name;$('#nearbyDetail').textContent=`${distance.toFixed(1)} m · ${ca.location}`;$('#mapArt').style.setProperty('--player-x',`${THREE.MathUtils.clamp(50+state.player.x*2,8,90)}%`);$('#mapArt').style.setProperty('--player-y',`${THREE.MathUtils.clamp(50+state.player.z*2,8,90)}%`);const dot=$('.map-player');if(dot){dot.style.left=`${THREE.MathUtils.clamp(50+state.player.x*2,8,90)}%`;dot.style.top=`${THREE.MathUtils.clamp(50+state.player.z*2,8,90)}%`;}}
function openModal({title,kicker='CENTRO DE APRENDIZAJE',description='',body='',wide=false,actions='',disclaimer=false}){const root=$('#modalRoot');root.innerHTML=`<div class="modal-scrim"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><header class="modal-head"><div><div class="modal-kicker">${esc(kicker)}</div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button class="modal-close" data-close aria-label="Cerrar">×</button></header><div class="modal-body">${body}${disclaimer?'<div class="disclaimer">Contenido educativo simulado. No sustituye formación acreditada, protocolos locales ni valoración de profesionales sanitarios. Casos y pacientes ficticios.</div>':''}${actions?`<div class="modal-actions">${actions}</div>`:''}</div></section></div>`;root.querySelector('[data-close]').onclick=closeModal;root.querySelector('.modal-scrim').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();});}
function closeModal(){$('#modalRoot').innerHTML='';state.procVital=null;}
function showCases(){const body=`<div class="case-grid">${CASES.map((ca,i)=>`<button class="case-card ${i===state.caseIndex?'selected':''}" data-case="${i}"><small>${esc(ca.id)} · ${esc(ca.difficulty)}</small><strong>${esc(ca.title)}</strong><p>${esc(ca.description)}</p><div class="case-meta"><span>${esc(ca.name)} · ${ca.age} años</span><span>${state.completed.includes(i)?'COMPLETADO':ca.location.toUpperCase()}</span></div></button>`).join('')}</div>`;
 openModal({title:'Casos clínicos',kicker:'TABLERO DE ASIGNACIONES',description:'Selecciona un caso ficticio para iniciar o continuar la práctica.',body,wide:true,disclaimer:true});document.querySelectorAll('[data-case]').forEach(btn=>btn.onclick=()=>{state.caseIndex=Number(btn.dataset.case);const p=caseMeshes[state.caseIndex].position;state.player.set(p.x+3,0,p.z+2.5);if(player)player.position.copy(state.player);updateHUD();closeModal();toast(`Caso ${c().id} seleccionado`);save();});}
function showChart(){const ca=c(),keys=VITALS;const cards=keys.map(v=>{const done=state.measured[ca.id]?.includes(v.key);const result=classify(ca,v.key);return `<div class="vital-card ${done?(result[1]==='warning'?'attention':'done'):'pending'}"><small>${esc(v.short)}</small><strong>${done?esc(v.value(ca)):`— —`}</strong><span>${done?esc(v.unit+' · '+result[0]):'PENDIENTE DE MEDICIÓN'}</span></div>`;}).join('');
 const body=`<div class="chart-top"><div class="chart-person">${ca.initials}</div><div><strong>${esc(ca.name)}, ${ca.age} años</strong><small>${esc(ca.id)} · ${esc(ca.location)} · ${esc(ca.reason)}</small></div></div><div class="chart-grid">${cards}</div><div class="field-grid"><div class="info-block"><small>ANTECEDENTES REFERIDOS</small><p>${esc(ca.history)}</p></div><div class="info-block"><small>OBSERVACIÓN DEL CASO</small><p>${esc(ca.observation)}</p></div></div><div class="info-block" style="margin-top:9px"><small>INTERPRETACIÓN EDUCATIVA</small><p>${esc(ca.note)}</p></div>`;
 openModal({title:'Expediente del paciente',kicker:'REGISTRO SIMULADO',description:'Los valores aparecen al completar cada procedimiento.',body,wide:true,disclaimer:true});}
function showProcedure(key){const vital=VITALS.find(v=>v.key===key);if(!vital)return;state.procVital=key;state.procStep=0;renderProcedure();}
function renderProcedure(){const vital=VITALS.find(v=>v.key===state.procVital);if(!vital)return;const ca=c();const steps=vital.steps.map((s,i)=>`<li class="${i<state.procStep?'done':i===state.procStep?'current':''}"><i>${i<state.procStep?'✓':String(i+1).padStart(2,'0')}</i>${esc(s)}</li>`).join('');let result='';if(state.procStep>=vital.steps.length){const [label,kind,explain]=classify(ca,vital.key);result=`<div class="procedure-result"><div><small>LECTURA SIMULADA · ${esc(label.toUpperCase())}</small><div class="procedure-note">${esc(explain)}</div></div><strong>${esc(vital.value(ca))}<small> ${esc(vital.unit)}</small></strong></div>`;}
 const body=`<div class="procedure"><div class="procedure-top"><small>PROCEDIMIENTO ${String(state.procStep+1).padStart(2,'0')} / ${vital.steps.length}</small><span>Equipo: ${esc(vital.tool)}</span></div><h3>${esc(vital.label)}</h3><p>Realiza los pasos de la práctica en orden. Lee cada indicación antes de continuar.</p><ol class="step-list">${steps}</ol>${result}</div><div class="procedure-note">Esta interacción es una actividad educativa, no una indicación para atender pacientes reales.</div>`;
 const final=state.procStep>=vital.steps.length;openModal({title:final?'Lectura registrada':vital.label,kicker:'VALORACIÓN VITAL',description:final?'Revisa la interpretación orientativa y continúa con el siguiente signo.':'Progreso de la técnica simulada.',body,actions:`<button class="btn" data-proc-cancel>Salir</button><button class="btn primary" data-proc-next>${final?'REGISTRAR Y CONTINUAR':'SIGUIENTE PASO'} <span>→</span></button>`,disclaimer:true});$('#modalRoot [data-proc-cancel]').onclick=closeModal;$('#modalRoot [data-proc-next]').onclick=()=>{if(state.procStep<vital.steps.length){state.procStep++;renderProcedure();return;}const measurements=state.measured[c().id]||(state.measured[c().id]=[]);if(!measurements.includes(vital.key))measurements.push(vital.key);save();updateHUD();closeModal();toast(`${vital.label}: registro guardado`);if(measurements.length===VITALS.length)completeCase();};}
