function completeCase(){const idx=state.caseIndex;if(state.completed.includes(idx))return;state.completed.push(idx);state.xp+=c().xp;state.coins+=c().coins;save();updateHUD();openModal({title:'Caso completado',kicker:'PRÁCTICA REGISTRADA',description:`Has completado las seis mediciones del caso ${c().id}.`,body:`<div class="procedure-result"><div><small>RECOMPENSA DE FORMACIÓN</small><div class="procedure-note">+${c().xp} XP · +${c().coins} fichas</div></div><strong>✦</strong></div><div class="info-block" style="margin-top:12px"><small>RECUERDA</small><p>${esc(c().note)}</p></div>`,actions:'<button class="btn primary" data-next-case>CONTINUAR →</button>',disclaimer:true});$('#modalRoot [data-next-case]').onclick=()=>{const next=CASES.findIndex((_,i)=>!state.completed.includes(i));closeModal();if(next>=0){state.caseIndex=next;const p=caseMeshes[next].position;state.player.set(p.x+3,0,p.z+2.5);player.position.copy(state.player);updateHUD();showAssessment();}else toast('¡Completaste todos los casos disponibles!');save();};}

