 openModal({title:'Expediente del paciente',kicker:'REGISTRO SIMULADO',description:'Los valores aparecen al completar cada procedimiento.',body,wide:true,disclaimer:true});}
function showProcedure(key){const vital=VITALS.find(v=>v.key===key);if(!vital)return;state.procVital=key;state.procStep=0;renderProcedure();}
function renderProcedure(){const vital=VITALS.find(v=>v.key===state.procVital);if(!vital)return;const ca=c();const steps=vital.steps.map((s,i)=>`<li class="${i<state.procStep?'done':i===state.procStep?'current':''}"><i>${i<state.procStep?'✓':String(i+1).padStart(2,'0')}</i>${esc(s)}</li>`).join('');let result='';if(state.procStep>=vital.steps.length){const [label,kind,explain]=classify(ca,vital.key);result=`<div class="procedure-result"><div><small>LECTURA SIMULADA · ${esc(label.toUpperCase())}</small><div class="procedure-note">${esc(explain)}</div></div><strong>${esc(vital.value(ca))}<small> ${esc(vital.unit)}</small></strong></div>`;}
 const body=`<div class="procedure"><div class="procedure-top"><small>PROCEDIMIENTO ${String(state.procStep+1).padStart(2,'0')} / ${vital.steps.length}</small><span>Equipo: ${esc(vital.tool)}</span></div><h3>${esc(vital.label)}</h3><p>Realiza los pasos de la práctica en orden. Lee cada indicación antes de continuar.</p><ol class="step-list">${steps}</ol>${result}</div><div class="procedure-note">Esta interacción es una actividad educativa, no una indicación para atender pacientes reales.</div>`;
