.procedure-note { font-size:9px;color:#9eb5c4;line-height:1.55;margin-top:12px }
.lesson { display:flex;align-items:center;gap:11px;border:1px solid #c5e8f01c;background:#102943;border-radius:8px;padding:11px }
.lesson-icon { width:34px;height:34px;display:grid;place-items:center;background:#45d6e817;border:1px solid #45d6e82b;border-radius:8px;color:var(--cyan);font-size:16px }
.lesson>div:nth-child(2) { flex:1 }
.lesson strong { font:600 11px Manrope;display:block }
.lesson p { font-size:9px;color:#91aabd;margin:4px 0 0;line-height:1.45 }
.lesson button { border:1px solid #a9cad72b;background:#17364e;border-radius:5px;color:#9ad9e2;padding:7px 9px;font:8px var(--mono) }
.toast { position:absolute;z-index:12;left:50%;bottom:73px;transform:translate(-50%,12px);opacity:0;transition:.25s;pointer-events:none;background:#102b42ee;border:1px solid #45d6e855;border-radius:7px;padding:10px 14px;color:#daf7fa;font:9px var(--mono);box- }
.toast.show { opacity:1;transform:translate(-50%,0) }
.disclaimer { border-top:1px solid #c5e8f01c;color:#7793a6;font-size:8px;line-height:1.55;padding-top:11px;margin-top:14px }
.intro-content { left:8% }
.intro-grid { background-position:center,center,58% center }
.objective-panel { padding:9px }
.objective-list { gap:5px }
.objective { font-size:8px }
.touch-controls { position:absolute;z-index:3;bottom:68px;left:15px;right:15px;display:flex;align-items:end;justify-content:space-between;pointer-events:none }
.intro-top { top:17px;left:16px;right:16px;font-size:7px;gap:8px }
.intro-tag { font-size:7px }
.intro-content { left:8%;top:46%;max-width:90% }
.intro h1 { font-size:clamp(43px,12vw,66px);letter-spacing:-3px;margin-top:18px }
.intro h1 em { letter-spacing:2px }
.intro-content>p { font-size:11px }
.intro-foot { width:90vw;top:calc(100% + 33px);gap:11px;flex-wrap:wrap }
.intro-foot span { width:100%;margin-bottom:0 }
.intro-side { right:18px;top:32% }
.intro-bottom { left:16px;right:16px;bottom:13px;font-size:6px;gap:12px }
.intro-bottom span:last-child { text-align:right }
.intro-grid { background-position:center,center,62% center }
.intro-credit { font-size:7px }
.modal-scrim { padding:10px }
.modal { max-height:88dvh }
.modal-head { padding:16px 15px 12px }
.modal-body { padding:13px 15px 16px }
.case-card { padding:10px }
.modal-head h2 { font-size:16px }
.objective-panel { max-height:153px;overflow:auto }

