+function recordMeasurement(key){
+  const c=activeCase();const list=state.measured[c.id]||(state.measured[c.id]=[]);
+  if(!list.includes(key)){list.push(key);state.xp+=20;toast(`${VITALS.find(v=>v.key===key).label} registrada · +20 XP`);}
