17: export function classify(caseData, key) {
18:   const v=caseData.vitals;
19:   if(key==='temp') return v.temp>=38 ? ['Atención contextual','warning','Temperatura simulada elevada; documenta el método y comunícalo.'] : ['Referencia educativa','normal','Interpreta junto con el estado general y el sitio de medición.'];
20:   if(key==='spo2') return v.spo2<94 ? ['Comunicar al responsable','warning','Lectura simulada reducida; verifica señal, contexto y comunica el hallazgo.'] : ['Referencia educativa','normal','Registra la lectura y el contexto; considera la calidad de señal.'];
21:   if(key==='rr') return v.rr>=22 ? ['Comunicar al responsable','warning','Frecuencia simulada elevada; valora esfuerzo y comunica cambios.'] : ['Referencia educativa','normal','Valora ritmo y esfuerzo, además del número.'];
22:   if(key==='hr'||key==='pulse') return v.hr>=100 || v.hr<60 ? ['Revisar contexto','warning','Compara con síntomas, reposo y características del pulso; comunica si preocupa.'] : ['Referencia educativa','normal','La frecuencia puede variar por actividad, edad y contexto.'];
23:   if(key==='bp') return v.bp[0]>=140||v.bp[1]>=90||v.bp[0]<90 ? ['Revisar contexto','warning','Un registro aislado no diagnostica; verifica técnica y comunícalo al responsable.'] : ['Referencia educativa','normal','La interpretación depende de técnica, edad, antecedentes y contexto.'];
24:   return ['Registro guardado','normal','Revisa todos los datos en conjunto.'];
25: }

