const sleep = ms => new Promise(r => setTimeout(r, ms));
async function waitForEndpoint() {
  for (let i=0;i<60;i++) { try { const r=await fetch('http://127.0.0.1:9222/json/list'); if(r.ok)return r.json(); } catch {} await sleep(250); }
  throw new Error('Chrome DevTools endpoint unavailable');
}
const targets=await waitForEndpoint();
const target=targets.find(t=>t.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);
let id=0; const pending=new Map(); const errors=[];
ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.method==='Log.entryAdded'&&m.params.entry.level==='error')errors.push(m.params.entry.text);});
await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true});});
function call(method,params={}){return new Promise((resolve,reject)=>{const n=++id;pending.set(n,m=>m.error?reject(new Error(m.error.message)):resolve(m.result));ws.send(JSON.stringify({id:n,method,params}));});}
async function evaluate(expression){const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.text);return r.result?.value;}
async function click(selector,index=0){return evaluate(`(()=>{const e=document.querySelectorAll(${JSON.stringify(selector)})[${index}];if(!e)throw new Error('Missing ${selector} index ${index}');e.click();return true})()`);}
async function screenshot(path, width, height){await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:width<700});await sleep(650);const r=await call('Page.captureScreenshot',{format:'jpeg',quality:90,fromSurface:true});await (await import('node:fs/promises')).writeFile(path,Buffer.from(r.data,'base64'));}
await call('Page.enable');await call('Runtime.enable');await call('Log.enable');await call('Page.navigate',{url:'http://127.0.0.1:5173/'});await sleep(1800);
const initial=await evaluate(`({title:document.title,canvas:!!document.querySelector('#world'),intro:!document.querySelector('#intro').classList.contains('hidden'),webgl:document.querySelector('#world').getContext('webgl2')!==null})`);
await click('#startGame');await sleep(800);
await click('[data-action="mission"]');await click('[data-case]',1);await click('[data-action="chart"]');
for(const key of ['bp','hr','rr','spo2','temp','pulse']){
 await click(`[data-measure="${key}"]`);
 for(let step=0;step<4;step++) await click('[data-next]');
 if(key!=='pulse'&&key!=='temp'&&key!=='spo2'&&key!=='rr'&&key!=='hr'&&key!=='bp'){};
 // The final measure opens completion, dismiss it before continuing.
 if(key==='pulse'){await click('[data-finish]');}
 else { const visible=await evaluate(`!!document.querySelector('[data-finish]')`);if(visible)await click('[data-finish]'); }
 // Return to the chart when the procedure record view remains open.
 if(!(await evaluate(`!!document.querySelector('[data-measure]')`)))await click('[data-action="chart"]');
}
const progress=await evaluate(`JSON.parse(localStorage.getItem('vital-force-save')||'{}')`);
await click('[data-action="academy"]');await click('[data-lesson]',0);await click('[data-answer]',0);await sleep(250);
const quiz=await evaluate(`JSON.parse(localStorage.getItem('vital-force-save')||'{}')`);
await click('[data-quiz-close]');await click('.modal-close');await sleep(350);
await screenshot('/home/runner/work/PlayGround/PlayGround/vital-force-desktop.jpg',1440,900);
await screenshot('/home/runner/work/PlayGround/PlayGround/vital-force-mobile.jpg',390,844);
const layout=await evaluate(`({desktop:{width:document.documentElement.clientWidth,height:document.documentElement.clientHeight},canvas:document.querySelector('#world').getBoundingClientRect().toJSON(),mobileOverflow:document.documentElement.scrollWidth>document.documentElement.clientWidth})`);
console.log(JSON.stringify({initial,completed:progress.completed,measurements:Object.values(progress.measured||{}).map(x=>x.length),quizDone:quiz.quizDone,layout,errors},null,2));
ws.close();

